#[cfg(test)]mod controls {
use super::{extract::FunctionUnit,lang::Lang,index::*,cluster::*,score::*,config::TestPolicy};
fn unit(i:u32,fp:Vec<u64>)->FunctionUnit{FunctionUnit{file:i,lang:Lang::Typescript,name:"f".into(),start_line:1,end_line:10,start_byte:0,end_byte:100,sig_lines:10,fingerprints:fp,is_test:false,is_trait_impl_method:false}}
#[test]fn hundred_identical_functions_keep_all4950pairs(){let mut f=(0..100).map(|i|unit(i,vec![1,2,3])).collect::<Vec<_>>();assert_eq!(find_pairs(&mut f,0.8,3).len(),4950);assert!(f.iter().all(|x|x.fingerprints==[1,2,3]));}
#[test]fn hundred_one_identical_functions_lose_all5050pairs(){let mut f=(0..101).map(|i|unit(i,vec![1,2,3])).collect::<Vec<_>>();assert_eq!(similarity(&f[0],&f[1]),1.0);assert!(find_pairs(&mut f,0.8,3).is_empty());assert!(f.iter().all(|x|x.fingerprints.is_empty()));assert_eq!(similarity(&f[0],&f[1]),0.0);}
#[test]fn connected_cluster_can_contain_below_threshold_member(){let mut f=vec![unit(0,vec![1,2]),unit(1,vec![1,2,3]),unit(2,vec![2,3])];let p=find_pairs(&mut f,0.6,1);assert_eq!(p.len(),2);let c=build_clusters(&f,&p);assert_eq!(c.len(),1);assert!(c[0].members.iter().any(|m|m.similarity<0.6));assert_eq!(c[0].deletable_lines,20);}
#[test]fn min_shared_can_drop_identical_short_sets(){let mut f=vec![unit(0,vec![1]),unit(1,vec![1])];assert_eq!(similarity(&f[0],&f[1]),1.0);assert!(find_pairs(&mut f,0.8,3).is_empty());}
#[test]fn zero_threshold_does_not_enumerate_disjoint_pairs(){let mut f=vec![unit(0,vec![1]),unit(1,vec![2])];assert!(find_pairs(&mut f,0.0,0).is_empty());}
#[test]fn nan_threshold_filters_every_pair(){let mut f=vec![unit(0,vec![1,2,3]),unit(1,vec![1,2,3])];assert!(find_pairs(&mut f,f64::NAN,3).is_empty());}
#[test]fn language_scope_suppresses_cross_language_pair(){let mut f=vec![unit(0,vec![1,2,3]),unit(1,vec![1,2,3])];f[1].lang=Lang::Rust;assert!(find_pairs(&mut f,0.8,3).is_empty());}
#[test]fn scoring_is_not_capped_for_arbitrary_supplied_cluster(){let c=Cluster{members:vec![],deletable_lines:200,test_only:false,trait_impl_only:false};let s=slop_score(&[c],100,TestPolicy::Include);assert_eq!(s.percent,200.0);assert_eq!(s.grade,'F');assert_eq!(s.deletable_lines,200);}
}
